/**
 * useTaxLienAuctions
 * Custom hook for managing auction state, filtering, and real-time updates.
 */
export function useTaxLienAuctions(initialFilters: Record<string, any> = {}) {
  const [auctions, setAuctions] = (typeof React !== 'undefined' ? React.useState<TaxLienAuction[]>([]) : [[] as TaxLienAuction[], (v: any) => {}]) as any;
  const [loading, setLoading] = (typeof React !== 'undefined' ? React.useState<boolean>(true) : [true, (v: any) => {}]) as any;
  const [error, setError] = (typeof React !== 'undefined' ? React.useState<string | null>(null) : [null, (v: any) => {}]) as any;

  const loadAuctions = async (filters = initialFilters) => {
    setLoading(true);
    try {
      const data = await TaxLienApiClient.fetchAuctions(filters);
      setAuctions(data);
      setError(null);
    } catch (err: any) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  if (typeof React !== 'undefined') {
    React.useEffect(() => {
      loadAuctions();
    }, []);
  }

  return { auctions, loading, error, refresh: loadAuctions };
}

