/**
 * AuditActor interface updated to match 2026-08-16 requirements:
 * - Must be an object, not a string.
 * - Does not contain 'name' property.
 */
export interface AuditActor {
  id: string;
  type: ActorType;
  role?: string;
  ipAddress?: string;
  userAgent?: string;
}

export interface GISCoordinates {
  latitude: number;
  longitude: number;
  elevation?: number;
  accuracy?: number;
  timestamp?: string;
}

export interface FinancialBreakdown {
  principal: number;
  accruedInterest: number;
  penalties: number;
  administrativeFees: number;
  legalFees: number;
  totalOwed: number;
  currency: string;
}

export interface TaxLienAuction {
  id: string;
  parcelNumber: string;
  county: string;
  state: string;
  year: number;
  assessedValue: number;
  backTaxesOwed: number;
  currentBid: number;
  bidType: BidType;
  minimumBid: number;
  auctionDate: Date;
  auctionEndDate: Date;
  redemptionPeriodMonths: number;
  status: AuctionStatus;
  legalDescription: string;
  gisCoordinates?: GISCoordinates;
  metadata: Record<string, any>;
  createdAt: Date;
  updatedAt: Date;
}

export interface Bid {
  id: string;
  auctionId: string;
  bidderId: string;
  bidAmount: number;
  bidInterestRate: number;
  status: BidStatus;
  timestamp: Date;
  txHash?: string;
  complianceId?: string;
}

export interface OwnedLien {
  id: string;
  auctionId: string;
  parcelNumber: string;
  county: string;
  state: string;
  purchasePrice: number;
  interestRate: number;
  purchaseDate: Date;
  redemptionDeadline: Date;
  status: LienStatus;
  accruedInterest: number;
  lastSyncTimestamp: Date;
  financials: FinancialBreakdown;
  documents: Array<{ type: string; url: string; hash: string }>;
}

export interface RedemptionEvent {
  id: string;
  lienId: string;
  redemptionDate: Date;
  amountPaid: number;
  payerId: string;
  paymentMethod: string;
  settlementStatus: 'pending' | 'completed' | 'failed';
  ledgerReference: string;
}

// ============================================================================
// ZOD VALIDATION SCHEMAS
// ============================================================================

export const AuctionQuerySchema = z.object({
  state: z.string().length(2).optional(),
  county: z.string().min(2).optional(),
  status: z.enum(['upcoming', 'active', 'closed']).optional(),
  minAssessedValue: z.coerce.number().nonnegative().optional(),
  maxBackTaxes: z.coerce.number().nonnegative().optional(),
  limit: z.coerce.number().int().positive().default(50),
  offset: z.coerce.number().int().nonnegative().default(0)
});

export const BidCreateSchema = z.object({
  auctionId: z.string().uuid(),
  bidderId: z.string().min(1),
  bidAmount: z.number().positive(),
  bidInterestRate: z.number().min(0).max(TAX_LIEN_CONFIG.MAX_BID_INTEREST_RATE),
  metadata: z.record(z.any()).optional()
});

export const RedemptionSchema = z.object({
  penaltyRate: z.number().min(0).max(100).default(0),
  flatFees: z.number().nonnegative().default(0),
  paymentMethodId: z.string().optional(),
  actor: z.object({
    id: z.string(),
    type: z.enum(['user', 'service', 'system', 'government_entity']),
    role: z.string().optional()
  }).optional()
});

export const SyncSchema = z.object({
  forceRefresh: z.boolean().default(false),
  lienIds: z.array(z.string().uuid()).optional(),
  targetState: z.string().length(2).optional()
});

