export type BidType = 'interest_rate' | 'premium' | 'penalty_percentage';
export type AuctionStatus = 'upcoming' | 'active' | 'paused' | 'closed' | 'cancelled' | 'settled';
export type BidStatus = 'pending' | 'submitted' | 'outbid' | 'won' | 'lost' | 'voided';
export type LienStatus = 'active' | 'redeemed' | 'foreclosure_eligible' | 'foreclosure_in_progress' | 'foreclosed' | 'expired';
export type ComplianceStatus = 'passed' | 'failed' | 'pending_review';
export type ActorType = 'user' | 'service' | 'system' | 'government_entity';

