/**
 * TaxLienApiClient provides a standardized interface for frontend applications
 * to interact with the Tax Lien Express API. It includes built-in error 
 * handling, telemetry hooks, and type-safe request/response cycles.
 */
export class TaxLienApiClient {
  private static baseUrl: string = '/api/tax-liens';

  private static async handleResponse<T>(response: Response): Promise<T> {
    if (!response.ok) {
      const errorData = await response.json().catch(() => ({}));
      throw new Error(errorData.error || `HTTP Error: ${response.status}`);
    }
    const result = await response.json();
    return result.data as T;
  }

  public static async fetchAuctions(filters?: Record<string, any>): Promise<TaxLienAuction[]> {
    const query = filters ? new URLSearchParams(filters as any).toString() : '';
    const response = await fetch(`${this.baseUrl}/auctions?${query}`);
    return this.handleResponse<TaxLienAuction[]>(response);
  }

  public static async fetchAuctionById(id: string): Promise<TaxLienAuction> {
    const response = await fetch(`${this.baseUrl}/auctions/${id}`);
    return this.handleResponse<TaxLienAuction>(response);
  }

  public static async placeBid(bidData: {
    auctionId: string;
    bidderId: string;
    bidAmount: number;
    bidInterestRate?: number;
  }): Promise<Bid> {
    const response = await fetch(`${this.baseUrl}/bids`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(bidData),
    });
    return this.handleResponse<Bid>(response);
  }

  public static async fetchPortfolio(): Promise<OwnedLien[]> {
    const response = await fetch(`${this.baseUrl}/portfolio`);
    return this.handleResponse<OwnedLien[]>(response);
  }

  public static async redeemLien(id: string, params: { penaltyRate?: number; flatFees?: number } = {}): Promise<{ lien: OwnedLien; totalRedemption: number }> {
    const response = await fetch(`${this.baseUrl}/portfolio/${id}/redeem`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(params),
    });
    return this.handleResponse<{ lien: OwnedLien; totalRedemption: number }>(response);
  }

  public static async triggerSync(): Promise<{ success: boolean; syncedCount: number }> {
    const response = await fetch(`${this.baseUrl}/sync`, { method: 'POST' });
    return this.handleResponse<{ success: boolean; syncedCount: number }>(response);
  }
}

