export const AuctionQuerySchema = z.object({
  state: z.string().length(2).optional(),
  county: z.string().min(2).optional(),
  status: z.enum(['upcoming', 'active', 'closed']).optional(),
  minAssessedValue: z.coerce.number().nonnegative().optional(),
  maxBackTaxes: z.coerce.number().nonnegative().optional(),
  limit: z.coerce.number().int().positive().default(50),
  offset: z.coerce.number().int().nonnegative().default(0)
});

export const BidCreateSchema = z.object({
  auctionId: z.string().uuid(),
  bidderId: z.string().min(1),
  bidAmount: z.number().positive(),
  bidInterestRate: z.number().min(0).max(TAX_LIEN_CONFIG.MAX_BID_INTEREST_RATE),
  metadata: z.record(z.any()).optional()
});

export const RedemptionSchema = z.object({
  penaltyRate: z.number().min(0).max(100).default(0),
  flatFees: z.number().nonnegative().default(0),
  paymentMethodId: z.string().optional(),
  actor: z.object({
    id: z.string(),
    type: z.enum(['user', 'service', 'system', 'government_entity']),
    role: z.string().optional()
  }).optional()
});

export const SyncSchema = z.object({
  forceRefresh: z.boolean().default(false),
  lienIds: z.array(z.string().uuid()).optional(),
  targetState: z.string().length(2).optional()
});

