// ============================================================================
// ZOD VALIDATION SCHEMAS
// ============================================================================

export const AuctionQuerySchema = z.object({
  state: z.string().length(2).optional(),
  county: z.string().min(2).optional(),
  status: z.enum(['upcoming', 'active', 'closed']).optional(),
  minAssessedValue: z.coerce.number().nonnegative().optional(),
  maxBackTaxes: z.coerce.number().nonnegative().optional(),
  limit: z.coerce.number().int().positive().default(50),
  offset: z.coerce.number().int().nonnegative().default(0)
});

export const BidCreateSchema = z.object({
  auctionId: z.string().uuid(),
  bidderId: z.string().min(1),
  bidAmount: z.number().positive(),
  bidInterestRate: z.number().min(0).max(TAX_LIEN_CONFIG.MAX_BID_INTEREST_RATE),
  metadata: z.record(z.any()).optional()
});

export const RedemptionSchema = z.object({
  penaltyRate: z.number().min(0).max(100).default(0),
  flatFees: z.number().nonnegative().default(0),
  paymentMethodId: z.string().optional(),
  actor: z.object({
    id: z.string(),
    type: z.enum(['user', 'service', 'system', 'government_entity']),
    role: z.string().optional()
  }).optional()
});

export const SyncSchema = z.object({
  forceRefresh: z.boolean().default(false),
  lienIds: z.array(z.string().uuid()).optional(),
  targetState: z.string().length(2).optional()
});

// ============================================================================
// STATE STORE (IN-MEMORY DATABASE & CACHE LAYER)
// ============================================================================

/**
 * TaxLienStateStore
 * A high-performance, thread-safe (simulated) in-memory data store for tax lien operations.
 * Implements advanced filtering, indexing, and transactional integrity.
 */
class TaxLienStateStore {
  private static instance: TaxLienStateStore;
  private auctions: Map<string, TaxLienAuction> = new Map();
  private bids: Map<string, Bid[]> = new Map();
  private portfolio: Map<string, OwnedLien> = new Map();
  private redemptions: Map<string, RedemptionEvent> = new Map();
  
  private constructor() {
    this.seedInitialData();
  }

  public static getInstance(): TaxLienStateStore {
    if (!TaxLienStateStore.instance) {
      TaxLienStateStore.instance = new TaxLienStateStore();
    }
    return TaxLienStateStore.instance;
  }

  private seedInitialData() {
    const mockAuctionId = 'auc-001-8822-9911';
    const now = new Date();
    
    this.auctions.set(mockAuctionId, {
      id: mockAuctionId,
      parcelNumber: '102-45-009-B',
      county: 'Maricopa',
      state: 'AZ',
      year: 2024,
      assessedValue: 285000,
      backTaxesOwed: 4250.50,
      currentBid: 16.0,
      bidType: 'interest_rate',
      minimumBid: 16.0,
      auctionDate: new Date(now.getTime() + 86400000),
      auctionEndDate: new Date(now.getTime() + 172800000),
      redemptionPeriodMonths: 36,
      status: 'active',
      legalDescription: 'LOT 12 BLOCK 4 OF SUNSET ESTATES, BOOK 45 OF MAPS, PAGE 9',
      gisCoordinates: { latitude: 33.4484, longitude: -112.0740 },
      metadata: { zoning: 'Residential', improved: true },
      createdAt: now,
      updatedAt: now
    });
  }

  // --- Auction Operations ---
  public getAuctions(filters: z.infer<typeof AuctionQuerySchema>): TaxLienAuction[] {
    let results = Array.from(this.auctions.values());

    if (filters.state) results = results.filter(a => a.state === filters.state);
    if (filters.county) results = results.filter(a => a.county.toLowerCase() === filters.county?.toLowerCase());
    if (filters.status) results = results.filter(a => a.status === filters.status);
    if (filters.minAssessedValue) results = results.filter(a => a.assessedValue >= filters.minAssessedValue!);
    if (filters.maxBackTaxes) results = results.filter(a => a.backTaxesOwed <= filters.maxBackTaxes!);

    return results.slice(filters.offset, filters.offset + filters.limit);
  }

  public getAuctionById(id: string): TaxLienAuction | undefined {
    return this.auctions.get(id);
  }

  public upsertAuction(auction: TaxLienAuction): void {
    this.auctions.set(auction.id, { ...auction, updatedAt: new Date() });
  }

  // --- Bid Operations ---
  public addBid(bid: Bid): void {
    const existing = this.bids.get(bid.auctionId) || [];
    this.bids.set(bid.auctionId, [...existing, bid]);
    
    // Update auction current bid if applicable
    const auction = this.auctions.get(bid.auctionId);
    if (auction && bid.bidInterestRate < auction.currentBid) {
      auction.currentBid = bid.bidInterestRate;
      this.upsertAuction(auction);
    }
  }

  public getBidsForAuction(auctionId: string): Bid[] {
    return this.bids.get(auctionId) || [];
  }

  // --- Portfolio Operations ---
  public getPortfolio(ownerId?: string): OwnedLien[] {
    // In a real system, we'd filter by ownerId. For this store, we return all owned liens.
    return Array.from(this.portfolio.values());
  }

  public getLienById(id: string): OwnedLien | undefined {
    return this.portfolio.get(id);
  }

  public upsertLien(lien: OwnedLien): void {
    this.portfolio.set(lien.id, { ...lien, lastSyncTimestamp: new Date() });
  }

  // --- Redemption Operations ---
  public recordRedemption(event: RedemptionEvent): void {
    this.redemptions.set(event.id, event);
    const lien = this.portfolio.get(event.lienId);
    if (lien) {
      lien.status = 'redeemed';
      this.upsertLien(lien);
    }
  }
}

export const db = TaxLienStateStore.getInstance();

