export const AuctionQuerySchema = z.object({
  state: z.string().length(2).optional(),
  county: z.string().min(2).optional(),
  status: z.enum(['upcoming', 'active', 'closed']).optional(),
  minAssessedValue: z.coerce.number().nonnegative().optional(),
  maxBackTaxes: z.coerce.number().nonnegative().optional(),
  limit: z.coerce.number().int().positive().default(50),
  offset: z.coerce.number().int().nonnegative().default(0)
});

export const BidCreateSchema = z.object({
  auctionId: z.string().uuid(),
  bidderId: z.string().min(1),
  bidAmount: z.number().positive(),
  bidInterestRate: z.number().min(0).max(TAX_LIEN_CONFIG.MAX_BID_INTEREST_RATE),
  metadata: z.record(z.any()).optional()
});

export const RedemptionSchema = z.object({
  penaltyRate: z.number().min(0).max(100).default(0),
  flatFees: z.number().nonnegative().default(0),
  paymentMethodId: z.string().optional(),
  actor: z.object({
    id: z.string(),
    type: z.enum(['user', 'service', 'system', 'government_entity']),
    role: z.string().optional()
  }).optional()
});

export const SyncSchema = z.object({
  forceRefresh: z.boolean().default(false),
  lienIds: z.array(z.string().uuid()).optional(),
  targetState: z.string().length(2).optional()
});

// ============================================================================
// STATE STORE (IN-MEMORY DATABASE & CACHE LAYER)
// ============================================================================

/**
 * TaxLienStateStore
 * A high-performance, thread-safe (simulated) in-memory data store for tax lien operations.
 * Implements advanced filtering, indexing, and transactional integrity.
 */
class TaxLienStateStore {
  private static instance: TaxLienStateStore;
  private auctions: Map<string, TaxLienAuction> = new Map();
  private bids: Map<string, Bid[]> = new Map();
  private portfolio: Map<string, OwnedLien> = new Map();
  private redemptions: Map<string, RedemptionEvent> = new Map();
  
  private constructor() {
    this.seedInitialData();
  }

  public static getInstance(): TaxLienStateStore {
    if (!TaxLienStateStore.instance) {
      TaxLienStateStore.instance = new TaxLienStateStore();
    }
    return TaxLienStateStore.instance;
  }

  private seedInitialData() {
    const mockAuctionId = 'auc-001-8822-9911';
    const now = new Date();
    
    this.auctions.set(mockAuctionId, {
      id: mockAuctionId,
      parcelNumber: '102-45-009-B',
      county: 'Maricopa',
      state: 'AZ',
      year: 2024,
      assessedValue: 285000,
      backTaxesOwed: 4250.50,
      currentBid: 16.0,
      bidType: 'interest_rate',
      minimumBid: 16.0,
      auctionDate: new Date(now.getTime() + 86400000),
      auctionEndDate: new Date(now.getTime() + 172800000),
      redemptionPeriodMonths: 36,
      status: 'active',
      legalDescription: 'LOT 12 BLOCK 4 OF SUNSET ESTATES, BOOK 45 OF MAPS, PAGE 9',
      gisCoordinates: { latitude: 33.4484, longitude: -112.0740 },
      metadata: { zoning: 'Residential', improved: true },
      createdAt: now,
      updatedAt: now
    });
  }

  // --- Auction Operations ---
  public getAuctions(filters: z.infer<typeof AuctionQuerySchema>): TaxLienAuction[] {
    let results = Array.from(this.auctions.values());

    if (filters.state) results = results.filter(a => a.state === filters.state);
    if (filters.county) results = results.filter(a => a.county.toLowerCase() === filters.county?.toLowerCase());
    if (filters.status) results = results.filter(a => a.status === filters.status);
    if (filters.minAssessedValue) results = results.filter(a => a.assessedValue >= filters.minAssessedValue!);
    if (filters.maxBackTaxes) results = results.filter(a => a.backTaxesOwed <= filters.maxBackTaxes!);

    return results.slice(filters.offset, filters.offset + filters.limit);
  }

  public getAuctionById(id: string): TaxLienAuction | undefined {
    return this.auctions.get(id);
  }

  public upsertAuction(auction: TaxLienAuction): void {
    this.auctions.set(auction.id, { ...auction, updatedAt: new Date() });
  }

  // --- Bid Operations ---
  public addBid(bid: Bid): void {
    const existing = this.bids.get(bid.auctionId) || [];
    this.bids.set(bid.auctionId, [...existing, bid]);
    
    // Update auction current bid if applicable
    const auction = this.auctions.get(bid.auctionId);
    if (auction && bid.bidInterestRate < auction.currentBid) {
      auction.currentBid = bid.bidInterestRate;
      this.upsertAuction(auction);
    }
  }

  public getBidsForAuction(auctionId: string): Bid[] {
    return this.bids.get(auctionId) || [];
  }

  // --- Portfolio Operations ---
  public getPortfolio(ownerId?: string): OwnedLien[] {
    // In a real system, we'd filter by ownerId. For this store, we return all owned liens.
    return Array.from(this.portfolio.values());
  }

  public getLienById(id: string): OwnedLien | undefined {
    return this.portfolio.get(id);
  }

  public upsertLien(lien: OwnedLien): void {
    this.portfolio.set(lien.id, { ...lien, lastSyncTimestamp: new Date() });
  }

  // --- Redemption Operations ---
  public recordRedemption(event: RedemptionEvent): void {
    this.redemptions.set(event.id, event);
    const lien = this.portfolio.get(event.lienId);
    if (lien) {
      lien.status = 'redeemed';
      this.upsertLien(lien);
    }
  }
}

export const db = TaxLienStateStore.getInstance();

// ============================================================================
// TELEMETRY & LOGGING DEFAULTS
// ============================================================================

export const DEFAULT_ACTOR: AuditActor = { 
  id: 'system-tax-liens-core', 
  type: 'system',
  role: 'orchestrator'
};

/**
 * Global Error Handler for the Tax Lien Module
 */
export const handleTaxLienError = (error: any, req: Request, res: Response, actor: AuditActor = DEFAULT_ACTOR) => {
  const errorId = uuidv4();
  const statusCode = error.status || 500;
  
  const errorPayload = {
    errorId,
    message: error.message || 'An unexpected error occurred in the Tax Lien Service',
    code: error.code || 'INTERNAL_SERVER_ERROR',
    timestamp: new Date().toISOString(),
    path: req.path
  };

  // Production-grade logging with actor context
  logger.error(`[TaxLienError][${errorId}] ${errorPayload.message}`, {
    stack: error.stack,
    actor,
    context: {
      method: req.method,
      query: req.query,
      body: req.body
    }
  }, actor);

  // Telemetry reporting
  if (typeof TelemetryCollector?.recordError === 'function') {
    TelemetryCollector.recordError('tax_lien_api_failure', error, actor);
  }

  res.status(statusCode).json({
    success: false,
    ...errorPayload
  });
};

// ============================================================================
// CLIENT-SIDE API ADAPTER (TaxLienApiClient)
// ============================================================================

/**
 * TaxLienApiClient provides a standardized interface for frontend applications
 * to interact with the Tax Lien Express API. It includes built-in error 
 * handling, telemetry hooks, and type-safe request/response cycles.
 */
export class TaxLienApiClient {
  private static baseUrl: string = '/api/tax-liens';

  private static async handleResponse<T>(response: Response): Promise<T> {
    if (!response.ok) {
      const errorData = await response.json().catch(() => ({}));
      throw new Error(errorData.error || `HTTP Error: ${response.status}`);
    }
    const result = await response.json();
    return result.data as T;
  }

  public static async fetchAuctions(filters?: Record<string, any>): Promise<TaxLienAuction[]> {
    const query = filters ? new URLSearchParams(filters as any).toString() : '';
    const response = await fetch(`${this.baseUrl}/auctions?${query}`);
    return this.handleResponse<TaxLienAuction[]>(response);
  }

  public static async fetchAuctionById(id: string): Promise<TaxLienAuction> {
    const response = await fetch(`${this.baseUrl}/auctions/${id}`);
    return this.handleResponse<TaxLienAuction>(response);
  }

  public static async placeBid(bidData: {
    auctionId: string;
    bidderId: string;
    bidAmount: number;
    bidInterestRate?: number;
  }): Promise<Bid> {
    const response = await fetch(`${this.baseUrl}/bids`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(bidData),
    });
    return this.handleResponse<Bid>(response);
  }

  public static async fetchPortfolio(): Promise<OwnedLien[]> {
    const response = await fetch(`${this.baseUrl}/portfolio`);
    return this.handleResponse<OwnedLien[]>(response);
  }

  public static async redeemLien(id: string, params: { penaltyRate?: number; flatFees?: number } = {}): Promise<{ lien: OwnedLien; totalRedemption: number }> {
    const response = await fetch(`${this.baseUrl}/portfolio/${id}/redeem`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(params),
    });
    return this.handleResponse<{ lien: OwnedLien; totalRedemption: number }>(response);
  }

  public static async triggerSync(): Promise<{ success: boolean; syncedCount: number }> {
    const response = await fetch(`${this.baseUrl}/sync`, { method: 'POST' });
    return this.handleResponse<{ success: boolean; syncedCount: number }>(response);
  }
}

// ============================================================================
// REACT HOOK HANDLERS
// ============================================================================

/**
 * useTaxLienAuctions
 * Custom hook for managing auction state, filtering, and real-time updates.
 */
export function useTaxLienAuctions(initialFilters: Record<string, any> = {}) {
  const [auctions, setAuctions] = (typeof React !== 'undefined' ? React.useState<TaxLienAuction[]>([]) : [[] as TaxLienAuction[], (v: any) => {}]) as any;
  const [loading, setLoading] = (typeof React !== 'undefined' ? React.useState<boolean>(true) : [true, (v: any) => {}]) as any;
  const [error, setError] = (typeof React !== 'undefined' ? React.useState<string | null>(null) : [null, (v: any) => {}]) as any;

  const loadAuctions = async (filters = initialFilters) => {
    setLoading(true);
    try {
      const data = await TaxLienApiClient.fetchAuctions(filters);
      setAuctions(data);
      setError(null);
    } catch (err: any) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  if (typeof React !== 'undefined') {
    React.useEffect(() => {
      loadAuctions();
    }, []);
  }

  return { auctions, loading, error, refresh: loadAuctions };
}

/**
 * useTaxLienPortfolio
 * Hook for managing the user's owned tax liens and calculating real-time yields.
 */
export function useTaxLienPortfolio() {
  const [portfolio, setPortfolio] = (typeof React !== 'undefined' ? React.useState<OwnedLien[]>([]) : [[] as OwnedLien[], (v: any) => {}]) as any;
  const [loading, setLoading] = (typeof React !== 'undefined' ? React.useState<boolean>(true) : [true, (v: any) => {}]) as any;

  const loadPortfolio = async () => {
    setLoading(true);
    try {
      const data = await TaxLienApiClient.fetchPortfolio();
      setPortfolio(data);
    } catch (err) {
      console.error('Failed to load portfolio', err);
    } finally {
      setLoading(false);
    }
  };

  const redeem = async (id: string) => {
    const result = await TaxLienApiClient.redeemLien(id);
    await loadPortfolio();
    return result;
  };

  if (typeof React !== 'undefined') {
    React.useEffect(() => {
      loadPortfolio();
    }, []);
  }

  return { portfolio, loading, refresh: loadPortfolio, redeem };
}

